#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;                       // 读入询问次数
    while (q--) {
        int x;
        cin >> x;                   // 读入当前 x
        // __builtin_popcount 计算 x 二进制中 '1' 的个数
        int cnt = __builtin_popcount(x);
        // 输出能量值 2 的 cnt 次幂
        cout << (1 << cnt) << '\n';
    }
    return 0;
}
